// ⚠️ Empieza en 'prueba': calcula y muestra todo, pero NO escribe en la base ni abre ninguna PR.
// Pasarlo a 'real' recién después de validar el alcance contra Ads Manager (ver la guía).
const MODO = 'prueba';

// Para correr un mes puntual (ya cerrado), completar las dos fechas como AAAA-MM-DD.
// Vacías = el mes anterior completo.
const DESDE_MANUAL = '';
const HASTA_MANUAL = '';

const zona = 'America/Argentina/Buenos_Aires';
const hoy = new Intl.DateTimeFormat('en-CA', { timeZone: zona }).format(new Date());
const pad = (n) => String(n).padStart(2, '0');

let desde;
let hasta;
if (DESDE_MANUAL || HASTA_MANUAL) {
  const formato = /^\d{4}-\d{2}-\d{2}$/;
  if (!formato.test(DESDE_MANUAL) || !formato.test(HASTA_MANUAL) || DESDE_MANUAL > HASTA_MANUAL) {
    throw new Error('Fechas manuales inválidas: usar AAAA-MM-DD y que "desde" no sea posterior a "hasta".');
  }
  desde = DESDE_MANUAL;
  hasta = HASTA_MANUAL;
} else {
  let [y, m] = hoy.split('-').map(Number);
  m -= 1;
  if (m === 0) { m = 12; y -= 1; }
  const ultimoDia = new Date(Date.UTC(y, m, 0)).getUTCDate();
  desde = `${y}-${pad(m)}-01`;
  hasta = `${y}-${pad(m)}-${pad(ultimoDia)}`;
}

if (hasta >= hoy) {
  throw new Error('La ventana tiene que estar cerrada: "hasta" debe ser anterior a hoy.');
}

return [{ json: { modo: MODO, desde, hasta, hoy } }];

// Junta en UN solo item todo lo que necesita el nodo de Python: la ventana, las listas del CRM y la respuesta de Windsor.
const ventana = $('Definir ventana').first().json;
const lista = (nombre) => $(nombre).all().map((i) => i.json).filter((j) => j && (j.id !== undefined || j.comunidad_id !== undefined));

const resp = $input.first().json || {};
const filas = Array.isArray(resp.data) ? resp.data : [];

return [{
  json: {
    ventana,
    comunidades: lista('Supabase: comunidades'),
    origenes: lista('Supabase: origen de Meta'),
    cuentas: lista('Supabase: cuentas de Meta'),
    windsor: { ok: Array.isArray(resp.data), filas },
  },
}];

parameters.pythonCode:
# Alcance de Meta por comunidad para la ventana completa.
# Entra UN item con: ventana, comunidades, origenes, cuentas y windsor {ok, filas}.
# Sale UN item por comunidad: alcance (o None con el motivo). Nunca inventa un número.
import unicodedata


def a_dict(x):
    # Compatible con el runner nativo (dict) y con Pyodide (JsProxy).
    return x.to_py() if hasattr(x, "to_py") else x


def norm(s):
    s = unicodedata.normalize("NFD", str(s or ""))
    s = "".join(c for c in s if unicodedata.category(c) != "Mn")
    return " ".join(s.lower().split())


def num(v):
    try:
        return int(float(v))
    except (TypeError, ValueError):
        return None


datos = a_dict(_items[0])["json"]
windsor = datos.get("windsor") or {}
filas = windsor.get("filas") or []
windsor_ok = bool(windsor.get("ok")) and len(filas) > 0

# Si la misma campaña+conjunto aparece en más de una fila, Windsor devolvió
# filas por día: el alcance no se puede sumar (se contaría varias veces a la misma persona).
vistas = {}
for f in filas:
    clave = (str(f.get("account_id", "")), norm(f.get("campaign")), norm(f.get("adset_name")))
    vistas[clave] = vistas.get(clave, 0) + 1
filas_por_dia = any(n > 1 for n in vistas.values())

origenes = {}
for o in datos.get("origenes", []):
    origenes.setdefault(o["comunidad_id"], []).append(o)

cuentas = {}
for c in datos.get("cuentas", []):
    cuentas[c["id"]] = str(c.get("meta_cuenta_id") or "").replace("act_", "").strip()

salida = []
for com in datos.get("comunidades", []):
    alcance, nota = None, None
    cuenta = cuentas.get(com["cliente_id"], "")
    mis_origenes = origenes.get(com["id"], [])

    if not windsor_ok:
        nota = "Windsor no devolvió datos"
    elif filas_por_dia:
        nota = "Windsor devolvió filas por día: el alcance no se puede sumar"
    elif not cuenta:
        nota = "El cliente no tiene cuenta de Meta cargada"
    elif not mis_origenes:
        nota = "La comunidad no tiene campaña de Meta asignada"
    else:
        halladas = {}
        for f in filas:
            if str(f.get("account_id", "")).replace("act_", "") != cuenta:
                continue
            for o in mis_origenes:
                if norm(f.get("campaign")) != norm(o.get("campana_nombre")):
                    continue
                # Sin conjunto de anuncios en el origen = toda la campaña va a esa comunidad.
                if o.get("adset_nombre") and norm(f.get("adset_name")) != norm(o["adset_nombre"]):
                    continue
                halladas[(norm(f.get("campaign")), norm(f.get("adset_name")))] = f
        if len(halladas) == 0:
            nota = "Windsor no devolvió datos de esa campaña en el mes"
        elif len(halladas) > 1:
            nota = "Varios conjuntos de anuncios en la comunidad: el alcance no se puede sumar"
        else:
            valor = num(list(halladas.values())[0].get("reach"))
            if valor is None or valor <= 0:
                nota = "Windsor devolvió alcance vacío"
            else:
                alcance = valor

    salida.append({"json": {
        "comunidad_id": com["id"],
        "cliente_id": com["cliente_id"],
        "nombre": com.get("nombre"),
        "alcance": alcance,
        "nota_alcance": nota,
    }})

return salida

parameters.jsCode:
// Une cada resultado del CRM (entradas, "Me sumo", miembros nuevos) con el alcance de su comunidad
// y decide si la ventana es elegible. Una ventana sin alcance NO es elegible: nunca se rellena con un valor supuesto.
const ventana = $('Definir ventana').first().json;

const alcances = {};
for (const i of $('Python: alcance por comunidad').all()) alcances[i.json.comunidad_id] = i.json;

const filas = [];
const avisos = [];
for (const item of $input.all()) {
  const r = item.json || {};
  if (!r.comunidad_id) {
    avisos.push(r.message || r.error || 'Respuesta vacía del CRM');
    continue;
  }
  const a = alcances[r.comunidad_id] || {};
  const elegible = Boolean(r.elegible) && a.alcance != null;
  filas.push({
    cliente_id: a.cliente_id,
    comunidad_id: r.comunidad_id,
    nombre: a.nombre,
    desde: ventana.desde,
    hasta: ventana.hasta,
    alcance: a.alcance ?? null,
    entradas_flow: r.entradas_flow,
    clics_me_sumo: r.clics_me_sumo,
    miembros_nuevos_total: r.miembros_nuevos_total,
    miembros_nuevos_con_flow: r.miembros_nuevos_con_flow,
    fechas_aproximadas: Boolean(r.fechas_aproximadas),
    elegible,
    motivo_no_elegible: elegible ? null : (r.motivo_no_elegible || a.nota_alcance || 'Sin motivo informado'),
    fuente_alcance: 'windsor',
  });
}

if (filas.length === 0) {
  throw new Error(`El CRM no devolvió ninguna comunidad calculada. ${avisos.join(' | ')}`);
}
if (avisos.length) filas[0]._avisos = avisos;

return filas.map((json) => ({ json }));

// Junta las ventanas ya guardadas en el CRM con las de esta corrida (en modo 'prueba' todavía no se guardaron).
// Si una ventana está en las dos, gana la de esta corrida.
const ventana = $('Definir ventana').first().json;

const guardadas = $input.all().map((i) => i.json).filter((j) => j && j.comunidad_id);
const actuales = $('Juntar embudo').all().map((i) => i.json).filter((j) => j && j.comunidad_id);

const porClave = new Map();
for (const f of [...guardadas, ...actuales]) {
  porClave.set(`${f.comunidad_id}|${f.desde}|${f.hasta}`, f);
}

return [{ json: { hoy: ventana.hoy, ventanas: [...porClave.values()] } }];

// Prepara la PR a Norte-kpi con el archivo de tasas medidas. Solo abre una PR (nunca mergea).
const t = $('Python: tasas y archivo').first().json;
const ventana = $('Definir ventana').first().json;
const master = $('GitHub: sha de master').first().json;
const actual = $input.first().json || {}; // GitHub: archivo actual (si no existe, no trae sha)

const RUTA = 'src/data/comunidadMedida.js';
const existe = Boolean(actual.sha);
const contenidoActual = existe ? Buffer.from(actual.content || '', 'base64').toString('utf8') : '';

// La fecha de generación cambia siempre: no cuenta para decidir si hay algo nuevo.
const sinFecha = (s) => s.replace(/\n\s*"generadoEn":.*\n?/, '\n');
const hayCambios = sinFecha(contenidoActual) !== sinFecha(t.archivo_js);

const rama = `medicion-comunidad-${ventana.hasta.slice(0, 7)}-${Date.now().toString(36)}`;
const porcentaje = (x) => (x == null ? '—' : `${(x * 100).toFixed(2)}%`);

return [{
  json: {
    hay_cambios: hayCambios,
    rama,
    sha_master: master.object && master.object.sha,
    put_body: {
      message: `Tasa de captación de Comunidad medida (cierre ${t.ultimoCierre})`,
      content: Buffer.from(t.archivo_js, 'utf8').toString('base64'),
      branch: rama,
      ...(existe ? { sha: actual.sha } : {}),
    },
    pr_body: {
      title: `Tasa de captación de Comunidad medida (cierre ${t.ultimoCierre})`,
      head: rama,
      base: 'master',
      body: [
        '## Qué cambia',
        `Actualiza \`${RUTA}\` con la tasa de captación medida en el CRM de Comunidades (miembros nuevos / alcance de la pauta).`,
        '',
        `- Ventanas mensuales elegibles: **${t.nVentanas}** de **${t.nClientes}** clientes`,
        `- Tasa mínima (conservadora): **${porcentaje(t.tasaMin)}**`,
        `- Tasa máxima: **${porcentaje(t.tasaMax)}**`,
        `- Último cierre: ${t.ultimoCierre}`,
        '',
        '## Antes de mergear',
        'Generada automáticamente por n8n. La calculadora todavía usa la estimación interna de `comunidad.js` hasta que otra PR lea este archivo.',
      ].join('\n'),
    },
  },
}];
